Translate("zhCN", "alterac-mountains", {
	title = "奥特兰克山脉",
	aliases = { "奥特兰克", "奥特兰克王国" },
	sections = {
		{
			title = "概述",
			text = [=[奥特兰克山脉耸立在{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}以北，是一道由积雪和灰色岩石构成的屏障，横亘在{red:lordamere-lake}洛丹米尔湖{/red}湖岸与瘟疫之地的死寂土地之间。它们曾经自成一国。王国的都城残破地躺在高山隘口之中，它的名字至今仍在{link:humans}人类{/link}的宫廷中被当作诅咒，因为奥特兰克在{link:alliance}联盟{/link}最黑暗的时刻背叛了它。如今，这片群山属于任何能守住它们的人：流亡的贵族和他们的亡命之徒、戴着窃来遗物的{link:ogres}食人魔{/link}、巫师、刺客、{link:orcs}兽人{/link}和{link:dwarves}矮人{/link}。]=],
