		{
			title = "概述",
			text = [=[达伦德农场是雾气湖岸上一座带有小港口的庄园，位于{link:razorfen-downs}高地{/link}西部与{red:lordamere-lake}洛丹米尔湖{/red}交会之处。这是{link:lord-aliden-perenolde}奥里登·匹瑞诺德领主{/link}的宅邸，他自称这片土地的领主。{link:syndicate}辛迪加{/link}的刺客和执行者守卫着它的大门。他的情妇{link:elysa}艾丽萨{/link}住在楼上，而站在他身旁的是{link:nagaz}纳伽兹{/link}，代表{link:argus-wake}阿古斯防卫军{/link}发言的{link:orcs}兽人{/link}。{link:tarren-mill}塔伦米尔{/link}的战士们知道通往这里的路。{link:southshore}南海镇{/link}的猎手们也知道。]=],
		},
	},
})

Translate("zhCN", "sofera-s-naze-and-corrahn-s-dagger", {
	title = "索菲亚高地与考兰之匕",
	aliases = { "索菲亚高地", "考兰之匕" },
	sections = {
		{
			title = "概述",
			text = [=[索菲亚高地和考兰之匕是从群山向丘陵延伸下来的两座山丘，位于{link:tarren-mill}塔伦米尔{/link}以北和以西。{link:syndicate}辛迪加{/link}在两处都设有营地。它的拦路强盗和盗贼从这里下山抢劫{link:hillsbrad-foothills}希尔斯布莱德{/link}的道路，而{link:southshore}南海镇{/link}相信，杀死上一任治安官的刺客也是从这里来的。在其中一座营地附近的山丘上，一个名叫仆从瓦里克的辛迪加爪牙受了伤躺在那里，讨价还价想要最后喝上一口。]=],
		},
	},
})

Translate("zhCN", "growless-cave", {
	title = "无草洞",
	sections = {
