	sections = {
		{
			title = "概述",
			text = [=[拉文霍德庄园隐藏在东部的山丘中，位于{link:alterac-mountains}奥特兰克{/link}与{link:hillsbrad-foothills}希尔斯布莱德{/link}交界处，在{link:durnholde-keep}敦霍尔德{/link}废墟的上方。没有公开的道路通向它。这里是{link:lord-jorach-ravenholdt}乔拉齐·拉文霍德公爵{/link}的宅邸，也是刺客{link:alliance}联盟{/link}的总部。北方大地上最出色的盗贼和杀手在这里接受训练、观察和考验。外人不受欢迎。不请自来的人很少能找到大门，而受邀者必须先证明自己的狡诈，才能抵达门前。联盟与{link:syndicate}辛迪加{/link}的战争已经持续了多年。]=],
		},
	},
})

Translate("zhCN", "lordamere-internment-camp", {
	title = "洛丹米尔收容所",
	sections = {
		{
			title = "概述",
			text = [=[洛丹米尔收容所坐落在{link:dalaran}达拉然{/link}附近的一座山丘上。{link:second-war}第二次战争{/link}之后，它是{link:lordaeron}洛丹伦{/link}的{link:internment-camps}收容所{/link}之一，战败的{link:orcs}兽人{/link}被关押在高墙之后。兽人已经离开了。如今达拉然的巫师们把收容所当作他们自己的{link:the-stockade}监狱{/link}。四名从{link:undercity}幽暗城{/link}的一座宝库中盗走神器的{link:forsaken}被遗忘者{/link}逃到了这里，法师们抓住了他们并将他们隔离。{link:warden-belamoore}典狱官贝拉摩尔{/link}看守着收容所，并研究这些盗贼所携带的东西。{link:sylvanas-windrunner}黑暗女王{/link}想要回她的神器。]=],
		},
	},
})

Translate("zhCN", "alterac-valley", {
	title = "奥特兰克山谷",
	sections = {
		{
			title = "概述",
			text = [=[在高峰以南，一条隧道通向奥特兰克山谷，这是群山之间一片冰雪与松林之地。{link:orcs}兽人{/link}的{link:frostwolf-clan}霜狼氏族{/link}宣称这座{link:stranglethorn-vale}山谷{/link}是他们的家园。{link:stormpike-guard}雷矛卫队{/link}的{link:dwarves}矮人{/link}来到这里挖掘遗物和矿石，并打算为{link:kingdom-of-ironforge}铁炉堡{/link}夺取这片土地。在隧道外，两支军队都设有营地。他们的军官接收新兵，考验他们，然后把他们送进山谷。山谷中的战斗从未真正停止过。]=],
		},
	},
})

Translate("zhCN", "old-dalaran-ruins", {
	title = "旧达拉然废墟",
	sections = {
		{
			title = "概述",
			text = [=[并非整个{link:dalaran}达拉然{/link}都重新崛起了。{link:third-war}第三次战争{/link}中{link:archimonde}阿克蒙德{/link}摧毁这座城市时，它的外围与核心一同毁坏。法师们在一道屏障之后建起了他们的新城，但旧城的废墟仍躺在{red:lordamere-lake}洛丹米尔湖{/red}湖岸。它的巫师和受束缚的{link:elements}元素{/link}曾在那里巡逻，{link:forsaken}被遗忘者{/link}的学者相信，石块之间仍埋藏着魔法宝藏。屏障消失之后，废墟向任何胆敢搜寻它们的人敞开。]=],
		},
	},
})

Translate("zhCN", "lord-jorach-ravenholdt", {
	title = "乔拉齐·拉文霍德公爵",
	subtitle = "刺客联盟领主",
	found = "拉文霍德庄园内",
	hint = "如果他的仆人肯放你进去，就去找东部山丘中那座隐秘庄园的领主。",
	allegiance = "刺客联盟 · 拉文霍德",
	aliases = { "乔拉齐·拉文霍德", "拉文霍德大师" },
	sections = {
		{
			title = "概述",
			text = [=[乔拉齐·拉文霍德公爵是{link:ravenholdt-manor}拉文霍德庄园{/link}的主人，也是刺客{link:alliance}联盟{/link}的领主。他的潜行者是北方大地上技艺最精湛的，他们不侍奉任何国王。他对客人彬彬有礼，对效力出色的人慷慨大方，对自己的事务则守口如瓶。他不说自己想要什么。他只是提出请求，然后等着看谁足够聪明能办到。]=],
		},
		{
			title = "意义",
