Translate("zhCN", "aiden-perenolde", {
	title = "艾登·佩雷诺德",
	subtitle = "奥特兰克的叛国之王",
	hint = "了解那位把自己的群山出卖给部落的国王的故事。",
	allegiance = "奥特兰克王国",
	aliases = { "佩雷诺德国王", "艾登·佩雷诺德领主" },
	sections = {
		{
			title = "概述",
			text = [=[艾登·佩雷诺德是{link:alterac-mountains}奥特兰克{/link}的最后一位国王。他说话温和，颇有教养，拥有一把精良的剑却从未用过。他在{link:alliance}联盟{/link}中的对手认为他是个懦夫。他却认为自己是唯一一位明智到能看出{link:horde}部落{/link}不可战胜的国王。在{link:second-war}第二次战争{/link}中，他为了保全自己的王国而背叛了联盟，却也因此失去了它。]=],
		},
		{
			title = "意义",
			text = [=[佩{link:farmer-ray}雷{/link}诺德的背叛是{link:alterac-mountains}奥特兰克{/link}沦为废墟的原因。他的继承人仍梦想着他所丧失的王冠，而他们所领导的{link:syndicate}辛迪加{/link}就是他苦涩的遗产。]=],
		},
		{
			title = "事迹",
			text = [=[• 他加入{link:alliance}洛丹伦联盟{/link}时心不甘情不愿，从一开始就对它心存疑虑。
• 他封锁了群山的隘口，随后与{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}秘密结盟，又打开了它们。
• 他杀害了带来{link:anduin-lothar}洛萨{/link}征兵令的信使，并把尸体藏在他的城堡里。
• 他被{link:terenas-menethil}泰瑞纳斯国王{/link}废黜，软禁在残破都城中他自己的宫殿里。]=],
		},
		{
			title = "未载之事",
			text = [=[没有任何编年史记载艾登·佩雷诺德是何时、如何死去的。据说在囚禁中，他的神智崩溃了。他的家人受到监视，而他的长子{link:lord-aliden-perenolde}奥里登{/link}曾徒劳地试图洗清家族的名声。]=],
		},
	},
	chapters = {
		{
			title = "敞开的隘口",
			hint = "了解部落为何能如此迅速地穿过奥特兰克。",
			text = [=[{link:horde}部落{/link}来到群山时，佩{link:farmer-ray}雷{/link}诺德派一只鸟去给部落的大酋长送信，并在夜里与他会面。他发现这个{link:orcs}兽人{/link}有教养、重荣誉。他们订立了条约：部落将安然通过，而{link:alterac-mountains}奥特兰克{/link}将得到保全。佩雷诺德把他的士兵调往北方，让南方的隘口空无一人。本应耗时数月的翻越只用了两天。直到{link:stromgarde-keep}激流堡{/link}的{link:thoras-trollbane}索拉斯·托尔贝恩{/link}进入奥特兰克，并让佩雷诺德自己的将军倒戈反对他，隘口才再次被封闭。]=],
		},
		{
			title = "失落的传家宝",
			hint = "找回奥特兰克王室的王冠。",
			text = [=[{link:alterac-mountains}奥特兰克{/link}陷落时，佩{link:farmer-ray}雷{/link}诺德王冠失落了。它由{link:dwarves}矮人{/link}珠宝匠打造，上面的绿宝石是他们最好的珍藏。{link:stormwind-city}暴风城{/link}的收货人至今仍想得到它。它最终出现在一名{link:ogres}食人魔{/link}法师手中，这名法师正在国王曾经戴着它的那座城市的废墟中寻宝。]=],
		},
	},
	mentions = {
		{ text = "佩{link:farmer-ray}雷{/link}诺德王冠" },
		{ text = "贵族之死，针对他已覆灭的宫廷中的贵族" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "奥里登·匹瑞诺德领主", note = "他的长子" },
		{ id = "orgrim-doomhammer", name = "奥格瑞姆·毁灭之锤", note = "他的秘密盟友" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "废黜他的国王" },
		{ id = "grel-borg-the-miser", name = "守财奴格雷尔伯格", note = "持有他家族的王冠" },
	},
})

