Translate("zhCN", "drek-thar", {
	title = "德雷克塔尔",
	subtitle = "霜狼氏族长者萨满",
	found = "霜狼要塞，奥特兰克山谷南部",
	hint = "寻找在奥特兰克山谷南端的霜狼要塞中统治的老萨满。",
	allegiance = "霜狼氏族 · 部落",
	aliases = { "德雷克塔尔" },
	sections = {
		{
			title = "概述",
			text = [=[德雷克塔尔是{link:frostwolf-clan}霜狼氏族{/link}的长者萨满，也是氏族在{link:alterac-valley}奥特兰克山谷{/link}的战士们的将军。他双目失明，年事已高。他在德拉诺时就是霜狼的萨满，并追随他的族人流放到这片群山之中。很久以前，他收留了一个名叫{link:thrall}萨尔{/link}的年轻{link:orcs}兽人{/link}，教他与灵魂交流。如今他在{link:stranglethorn-vale}山谷{/link}南部的要塞中领导着霜狼。]=],
		},
		{
			title = "意义",
			text = [=[德雷克塔尔是大酋长的老师。通过他，萨满的古老之道回到了{link:orcs}兽人{/link}之中；又通过{link:thrall}萨尔{/link}，回到了整个{link:horde}部落{/link}之中。]=],
		},
		{
			title = "事迹",
			text = [=[• 他让{link:frostwolf-clan}霜狼{/link}在{link:alterac-mountains}奥特兰克{/link}的流放中存活下来。
• 他向{link:thrall}萨尔{/link}传授萨满之道，并向他揭示了他的父母是谁。
• 他领导着{link:alterac-valley}奥特兰克山谷{/link}的防御，抵御{link:stormpike-guard}雷矛卫队{/link}。]=],
		},
	},
	chapters = {
		{
			title = "杜隆坦之子",
			hint = "了解大酋长是如何来到霜狼之中的。",
			text = [=[一个由{link:humans}人类{/link}抚养长大的年轻{link:orcs}兽人{/link}来到{link:frostwolf-clan}霜狼{/link}营地时，带着一块他婴儿时期的破毯子。德雷克塔尔认得上面的图案。这个陌生人是杜隆坦之子，杜隆坦正是那位率领氏族走上流放之路、后来与他的伴侣一同被谋杀的酋长。老萨满考验了这个年轻兽人的骄傲与谦逊，然后教他灵魂之道。]=],
		},
		{
			title = "保卫霜狼",
			hint = "与霜狼一同守卫他们的山谷。",
			text = [=[如今，{link:dwarves}矮人{/link}闯入了这座在{link:frostwolf-clan}霜狼{/link}最黑暗的岁月里庇护他们的{link:stranglethorn-vale}山谷{/link}。大酋长所珍视的氏族正遭受攻击，号召已传遍整个{link:horde}部落{/link}。战士们被派往{link:tarren-mill}塔伦米尔{/link}以北，去找战争大师{link:rhag-garmason}拉格{/link}隆德，他在山谷入口考验他们，然后再让他们去作战。]=],
		},
	},
	mentions = {
		{ text = "保卫{link:frostwolf-clan}霜狼{/link}" },
		{ text = "{link:alterac-mountains}奥特兰克{/link}之战" },
		{ text = "实验场" },
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "他的学生和大酋长" },
		{ id = "vanndar-stormpike", name = "范达尔·雷矛", note = "他的敌人" },
		{ id = "voggah-deathgrip", name = "沃加·死爪", note = "派战士前来援助他" },
	},
})

Translate("zhCN", "crushridge-ogres", {
	title = "破碎岭食人魔",
	aliases = { "破碎岭", "破碎岭氏族" },
	sections = {
		{
			title = "概述",
			text = [=[破碎岭是一支{link:ogres}食人魔{/link}战团，他们把{link:alterac-mountains}奥特兰克{/link}旧都的废墟据为己有。蛮兵、重击者、战争贩子、执行者和法师挤满了奥特兰克诸王曾经骑马经过的街道。他们在附近的山丘中挖掘了一座巨大的土丘，又在群山更深处挖掘了第二座，他们的巡逻队守卫着通往{link:tarren-mill}塔伦米尔{/link}的{link:the-crossroads}十字路口{/link}。]=],
		},
		{
			title = "意志之冠",
			text = [=[破碎岭并非自愿来到{link:alterac-mountains}奥特兰克{/link}。他们的督军{link:mug-thol}玛格索尔{/link}曾被迫为{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}效力，她派他的战团前往群山寻找一件名为意志之冠的遗物。玛格索尔找到了王冠，并把它戴在了头上。它使他摆脱了黑暗女王的控制，他的{link:ogres}食人魔{/link}追随他进入废墟，成了自己的主人。三名副官塔格、玛克拉克和戈洛姆斯站在他身旁，而食人魔法师{link:grel-borg-the-miser}格雷布格{/link}在城中搜寻宝藏。]=],
		},
		{
			title = "四面皆敌",
			text = [=[{link:tarren-mill}塔伦米尔{/link}的{link:forsaken}被遗忘者{/link}想要那顶王冠，连同{link:mug-thol}玛格索尔{/link}和他副官们的人头。{link:southshore}南海镇{/link}的士兵担心{link:ogres}食人魔{/link}会下到丘陵地带，他们的元帅为每一个被杀的食人魔悬赏。食人魔还与{link:syndicate}辛迪加{/link}争夺这个双方都宣称拥有的王国的废墟。]=],
		},
	},
})

Translate("zhCN", "argus-wake", {
	title = "阿古斯防卫军",
	sections = {
		{
			title = "概述",
			text = [=[阿古斯防卫军是一个秘密组织，它让自己成为了{link:syndicate}辛迪加{/link}在{link:alterac-mountains}奥特兰克{/link}的盟友。它的暗影法师在{link:razorfen-downs}高地{/link}等待，它的大祭司、{link:orcs}兽人{/link}{link:nagaz}纳伽兹{/link}站在{link:lord-aliden-perenolde}奥里登·匹瑞诺德领主{/link}身旁。奥特兰克的贵族们以为自己找到了强大的朋友。他们错了。]=],
		},
		{
			title = "信件",
			text = [=[真相是在一座{link:syndicate}辛迪加{/link}营地中找到的一封信里揭露的。它用一种极为罕见的密码写成，就连{link:southshore}南海镇{/link}的博学者也无法解读，只能把它送到{link:ironforge}铁炉堡{/link}的一位勘探员那里。这封信是{link:nagaz}纳伽兹{/link}写给防卫军首领的，他称此人为由一个{link:shadow-council}议会{/link}任命的主人。他写道，辛迪加将在防卫军的指引下夺回{link:alterac-mountains}奥特兰克{/link}，然后夺取{link:stromgarde-keep}激流堡{/link}。有了一个国家和一个属于自己的权力基础，防卫军就将为他所称的第三大军铺平道路。他以{link:sargeras}萨格拉斯{/link}之名署名。]=],
		},
		{
			title = "未知之事",
			text = [=[{link:southshore}南海镇{/link}的治安官{link:magistrate-henry-maleb}马雷布{/link}派猎手去追捕{link:nagaz}纳伽兹{/link}和他的法师。即便如此，治安官也知道纳伽兹只是一个仆从。谁在领导阿古斯防卫军，它的根基延伸得有多远，南海镇没有人说得出来。]=],
		},
	},
})

Translate("zhCN", "stormpike-guard", {
	title = "雷矛卫队",
	aliases = { "雷矛远征队", "雷矛" },
	sections = {
		{
			title = "概述",
			text = [=[雷矛卫队是雷矛氏族的{link:dwarves}矮人{/link}在{link:alterac-valley}奥特兰克山谷{/link}的一支远征队，由{link:vanndar-stormpike}范达尔·雷矛{/link}将军指挥。他们从{link:stranglethorn-vale}山谷{/link}北部的丹巴{link:dar}达尔{/link}要塞出发，在这片土地上寻找矿石和他们往昔的遗物。{link:alliance}联盟{/link}的{link:humans}人类{/link}、{link:gnomes}侏儒{/link}和{link:night-elves}暗夜精灵{/link}也在他们的队伍中作战。]=],
		},
		{
			title = "王令",
			text = [=[远征已经变成了一场战争。{link:magni-bronzebeard}麦格尼·铜须{/link}国王宣布，夺取{link:alterac-mountains}奥特兰克{/link}的{link:stranglethorn-vale}山谷{/link}是{link:kingdom-of-ironforge}铁炉堡王国{/link}的义务，雷矛为了占领山谷而与冰斧{link:trolls}巨魔{/link}和{link:frostwolf-clan}霜狼氏族{/link}的{link:orcs}兽人{/link}作战。{link:explorers-league}探险者协会{/link}的学者们与他们同行，确信山谷中藏有值得为之一战的神器。兽人称他们为侵略者。{link:dwarves}矮人{/link}则称山谷理所当然属于他们。]=],
		},
		{
			title = "当今",
			text = [=[在通往{link:stranglethorn-vale}山谷{/link}的隧道外，雷矛的军官们接收{link:alliance}联盟{/link}的士兵，在山谷的洞穴中考验他们，并授予他们卫队的徽章。{link:dwarves}矮人{/link}的山羊在{link:dun-morogh}丹莫罗{/link}的{link:amberstill-ranch}冻石农场{/link}培育，被送往北方增援远征队。]=],
		},
	},
})

Translate("zhCN", "frostwolf-clan", {
	title = "霜狼氏族",
	aliases = { "霜狼", "霜狼兽人" },
	sections = {
		{
			title = "概述",
			text = [=[霜狼氏族是一个以{link:alterac-valley}奥特兰克山谷{/link}为家园的{link:orcs}兽人{/link}氏族。这是{link:thrall}萨尔{/link}父亲的氏族，大酋长对它十分珍视。它的战士骑着群山中巨大的白狼，它的长者萨满{link:drek-thar}德雷克塔尔{/link}从{link:stranglethorn-vale}山谷{/link}南部的霜狼要塞领导着它。]=],
		},
		{
			title = "流放",
			text = [=[在德拉诺，霜狼是一个骄傲的氏族，由他们的酋长杜隆坦领导。{link:orcs}兽人{/link}来到{link:azeroth}艾泽拉斯{/link}时，杜隆坦公开反对{link:gul-dan}古尔丹{/link}和{link:horde}部落{/link}所走的黑暗道路。为此，他的氏族被放逐到{link:alterac-mountains}奥特兰克山脉{/link}。杜隆坦和他的伴侣后来离开了{link:stranglethorn-vale}山谷{/link}，两人都被古尔丹的爪牙谋杀。他们的幼子被一名{link:humans}人类{/link}军官发现，那人把他当作奴隶在{link:durnholde-keep}敦霍尔德{/link}抚养长大。霜狼独自忍受着严寒和漫长的岁月，远离部落的{link:fel-magic}邪能魔法{/link}，他们的萨满重新学会了灵魂之道。]=],
		},
		{
			title = "儿子的归来",
			text = [=[多年以后，一个从{link:durnholde-keep}敦霍尔德{/link}逃出来的年轻{link:orcs}兽人{/link}来到了他们的营地。他是杜隆坦之子。{link:drek-thar}德雷克塔尔{/link}教他萨满之道，{link:thrall}萨尔{/link}从{link:stranglethorn-vale}山谷{/link}出发，去解放{link:internment-camps}收容所{/link}中的兽人，并建立了一个新的{link:horde}部落{/link}。]=],
		},
		{
			title = "当今",
			text = [=[如今，{link:stormpike-guard}雷矛卫队{/link}的{link:dwarves}矮人{/link}闯入了{link:stranglethorn-vale}山谷{/link}。霜狼不会交出他们的家园，而{link:horde}部落{/link}已经响应了他们的号召。]=],
		},
	},
})
